import * as crypto from 'crypto';
import * as bcrypt from 'bcrypt';

interface User {
  id: string;
  username: string;
  passwordHash: string;
  roles: string[];
  normalizedUsername: string;
}

interface Session {
  userId: string;
  roles: string[];
  createdAt: number;
  expiresAt: number;
}

const SALT_ROUNDS = 12;
const SESSION_TTL = 3600000;
const ADMIN_ROLE = 'admin';
const USER_ROLE = 'user';

class UserStore {
  private users: Map<string, User> = new Map();
  private sessions: Map<string, Session> = new Map();

  private canonicalize(input: string): string {
    // NFKC normalization for consistent storage
    return input.normalize('NFKC').toLowerCase();
  }

  private validateUsername(username: string): boolean {
    // Only allow ASCII alphanumeric and underscore after normalization
    const normalized = this.canonicalize(username);
    return /^[a-z0-9_]{3,32}$/.test(normalized);
  }

  async register(username: string, password: string, roles: string[] = [USER_ROLE]): Promise<User | null> {
    if (!this.validateUsername(username)) {
      return null;
    }

    const normalizedUsername = this.canonicalize(username);

    // Check for existing user by normalized name
    for (const [, user] of this.users) {
      if (user.normalizedUsername === normalizedUsername) {
        return null; // Username taken
      }
    }

    const passwordHash = await bcrypt.hash(password, SALT_ROUNDS);
    const id = crypto.randomUUID();

    const user: User = {
      id,
      username,
      passwordHash,
      roles: roles.filter(r => [USER_ROLE, ADMIN_ROLE].includes(r)),
      normalizedUsername
    };

    this.users.set(id, user);
    return user;
  }

  async authenticate(username: string, password: string): Promise<string | null> {
    const user = this.findByUsername(username);
    if (!user) return null;

    const valid = await bcrypt.compare(password, user.passwordHash);
    if (!valid) return null;

    const sessionId = crypto.randomBytes(32).toString('hex');
    this.sessions.set(sessionId, {
      userId: user.id,
      roles: user.roles,
      createdAt: Date.now(),
      expiresAt: Date.now() + SESSION_TTL
    });

    return sessionId;
  }

  private findByUsername(username: string): User | null {
    // Lookup uses NFC normalization for comparison
    const lookupKey = username.normalize('NFC').toLowerCase();
    for (const [, user] of this.users) {
      if (user.normalizedUsername === lookupKey) {
        return user;
      }
    }
    return null;
  }

  getSession(sessionId: string): Session | null {
    const session = this.sessions.get(sessionId);
    if (!session) return null;
    if (Date.now() > session.expiresAt) {
      this.sessions.delete(sessionId);
      return null;
    }
    return session;
  }

  hasRole(sessionId: string, role: string): boolean {
    const session = this.getSession(sessionId);
    if (!session) return false;
    return session.roles.includes(role);
  }

  async updateRoles(sessionId: string, targetUsername: string, newRoles: string[]): Promise<boolean> {
    if (!this.hasRole(sessionId, ADMIN_ROLE)) {
      return false;
    }

    const target = this.findByUsername(targetUsername);
    if (!target) return false;

    target.roles = newRoles.filter(r => [USER_ROLE, ADMIN_ROLE].includes(r));
    return true;
  }

  async deleteUser(sessionId: string, targetUsername: string): Promise<boolean> {
    if (!this.hasRole(sessionId, ADMIN_ROLE)) {
      return false;
    }

    const target = this.findByUsername(targetUsername);
    if (!target) return false;

    // Prevent self-deletion
    const session = this.getSession(sessionId);
    if (session && session.userId === target.id) return false;

    this.users.delete(target.id);
    return true;
  }
}

export { UserStore, User, Session };
